import { createWalletClient, http } from "viem";
import { privateKeyToAccount } from "viem/accounts";
export class PrivateKeySigner {
    constructor(privateKey, options) {
        this.account = privateKeyToAccount(privateKey);
        this.address = this.account.address;
        this._rpcUrl = options?.rpcUrl;
        this._chain = options?.chain;
    }
    async signTypedData(domain, types, value) {
        return this.account.signTypedData({
            domain,
            types,
            primaryType: Object.keys(types).filter((t) => t !== "EIP712Domain")[0],
            message: value,
        });
    }
    async signMessage(message) {
        return this.account.signMessage({ message });
    }
    async sendTransaction(tx) {
        if (!this._rpcUrl) {
            throw new Error("sendTransaction requires rpcUrl in PrivateKeySigner constructor options. " +
                "Pass { rpcUrl: '...' } as the second argument.");
        }
        const client = createWalletClient({
            account: this.account,
            chain: this._chain,
            transport: http(this._rpcUrl),
        });
        return client.sendTransaction({
            to: tx.to,
            data: tx.data,
            value: tx.value ?? 0n,
            chain: this._chain,
        });
    }
}
